import { defineUserSignupFields } from "wasp/server/auth";

// Extra fields that get saved onto the `User` entity when a user signs up
// using the username & password auth method.
//
// Note: we deliberately don't include `password` here - Wasp's auth backend
// handles hashing and storing the password in the `AuthIdentity` entity, and
// including `password` here would risk saving it as plain text.
export const userSignupFields = defineUserSignupFields({
  username: (data) => {
    if (typeof data.username !== "string" || data.username.length === 0) {
      throw new Error("username is required");
    }
    return data.username;
  },
  // Anyone who signs up through the public signup form becomes a customer.
  // Agents and managers are created via the database seed.
  role: () => "CUSTOMER",
});

import type { DbSeedFn, PrismaClient } from "wasp/server";
import { sanitizeAndSerializeProviderData } from "wasp/server/auth";

async function createUserWithAuth(
  prisma: PrismaClient,
  data: { username: string; password: string; role: string },
) {
  return prisma.user.create({
    data: {
      username: data.username,
      password: data.password,
      role: data.role,
      auth: {
        create: {
          identities: {
            create: {
              providerName: "username",
              providerUserId: data.username,
              providerData: await sanitizeAndSerializeProviderData<"username">(
                {
                  hashedPassword: data.password,
                },
              ),
            },
          },
        },
      },
    },
  });
}

export const seedData: DbSeedFn = async (prisma) => {
  await createUserWithAuth(prisma, {
    username: "manager",
    password: "password123",
    role: "MANAGER",
  });

  await createUserWithAuth(prisma, {
    username: "agent1",
    password: "password123",
    role: "AGENT",
  });

  await createUserWithAuth(prisma, {
    username: "agent2",
    password: "password123",
    role: "AGENT",
  });

  await createUserWithAuth(prisma, {
    username: "customer1",
    password: "password123",
    role: "CUSTOMER",
  });
};

import type { Ticket, User } from "wasp/entities";
import type { GetAgents, GetTickets } from "wasp/server/operations";

export type TicketWithRelations = Ticket & {
  assignee: User | null;
  creator: User;
};

export const getTickets: GetTickets<void, TicketWithRelations[]> = async (
  _args,
  context,
) => {
  return context.entities.Ticket.findMany({
    include: {
      assignee: true,
      creator: true,
    },
    orderBy: { id: "asc" },
  });
};

export type AgentWithWorkload = User & { workload: number };

export const getAgents: GetAgents<void, AgentWithWorkload[]> = async (
  _args,
  context,
) => {
  const agents = await context.entities.User.findMany({
    where: { role: "AGENT" },
    orderBy: { id: "asc" },
  });

  const agentsWithWorkload = await Promise.all(
    agents.map(async (agent) => {
      const workload = await context.entities.Ticket.count({
        where: {
          assigneeId: agent.id,
          status: { not: "RESOLVED" },
        },
      });
      return { ...agent, workload };
    }),
  );

  return agentsWithWorkload;
};

import { HttpError } from "wasp/server";
import type { Ticket } from "wasp/entities";
import type {
  CreateTicket,
  SimulateSlaBreach,
} from "wasp/server/operations";

export type Priority = "HIGH" | "MEDIUM" | "LOW";

const SLA_SECONDS: Record<Priority, number> = {
  HIGH: 3600,
  MEDIUM: 14400,
  LOW: 86400,
};

type CreateTicketInput = {
  title: string;
  description: string;
  priority: Priority;
};

export const createTicket: CreateTicket<CreateTicketInput, Ticket> = async (
  args,
  context,
) => {
  if (!context.user) {
    throw new HttpError(401, "You must be logged in to create a ticket");
  }

  const { title, description, priority } = args;

  const now = new Date();
  const slaDeadline = new Date(
    now.getTime() + SLA_SECONDS[priority] * 1000,
  );

  // Find the agent with the lowest number of active (unresolved) tickets.
  // Ties are broken by picking the agent with the smallest id.
  const agents = await context.entities.User.findMany({
    where: { role: "AGENT" },
    orderBy: { id: "asc" },
  });

  let assigneeId: number | undefined;

  if (agents.length > 0) {
    const agentsWithWorkload = await Promise.all(
      agents.map(async (agent) => {
        const workload = await context.entities.Ticket.count({
          where: {
            assigneeId: agent.id,
            status: { not: "RESOLVED" },
          },
        });
        return { id: agent.id, workload };
      }),
    );

    agentsWithWorkload.sort((a, b) => {
      if (a.workload !== b.workload) {
        return a.workload - b.workload;
      }
      return a.id - b.id;
    });

    assigneeId = agentsWithWorkload[0].id;
  }

  const ticket = await context.entities.Ticket.create({
    data: {
      title,
      description,
      priority,
      slaDeadline,
      creator: { connect: { id: context.user.id } },
      ...(assigneeId !== undefined
        ? { assignee: { connect: { id: assigneeId } } }
        : {}),
    },
  });

  return ticket;
};

type SimulateSlaBreachInput = {
  ticketId: number;
};

const TWO_HOURS_MS = 2 * 60 * 60 * 1000;

export const simulateSlaBreach: SimulateSlaBreach<
  SimulateSlaBreachInput,
  Ticket
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "You must be logged in");
  }

  const { ticketId } = args;

  const ticket = await context.entities.Ticket.findUnique({
    where: { id: ticketId },
  });

  if (!ticket) {
    throw new HttpError(404, "Ticket not found");
  }

  const newCreatedAt = new Date(ticket.createdAt.getTime() - TWO_HOURS_MS);
  const newSlaDeadline = new Date(
    ticket.slaDeadline.getTime() - TWO_HOURS_MS,
  );

  let updatedTicket = await context.entities.Ticket.update({
    where: { id: ticketId },
    data: {
      createdAt: newCreatedAt,
      slaDeadline: newSlaDeadline,
    },
  });

  const isBreached =
    updatedTicket.slaDeadline.getTime() < Date.now() &&
    updatedTicket.status !== "RESOLVED" &&
    !updatedTicket.isEscalated;

  if (isBreached) {
    const manager = await context.entities.User.findFirst({
      where: { role: "MANAGER" },
      orderBy: { id: "asc" },
    });

    updatedTicket = await context.entities.Ticket.update({
      where: { id: ticketId },
      data: {
        isEscalated: true,
        ...(manager
          ? { assignee: { connect: { id: manager.id } } }
          : {}),
      },
    });
  }

  return updatedTicket;
};

